using System;
using System.IO;
using System.Reflection;
using System.Collections;
using System.Linq;
using System.Threading;
using System.Web.Script.Serialization;
using HarmonyLib;
namespace Local36 {
 // Testing-flag gated observation of native healing only. Prefix/postfix never
 // skips a method or changes arguments, HP, charge, damage, actor or game state.
 public static class BattleAudit36 {
  public sealed class Turn {public object actor;public int user,before,max,stone,nominal,countBefore;public bool special,alreadyAttacking;public string gameType;}
  [ThreadStatic]static Turn Current;
  static string Root;static readonly object Gate=new object();
  static Timer GamesTimer;static string LastGames;
  static object Get(object value,string name){if(value==null)return null;var type=value.GetType();var p=type.GetProperty(name);if(p!=null)return p.GetValue(value,null);for(;type!=null;type=type.BaseType){var f=type.GetField(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly);if(f!=null)return f.GetValue(value);}return null;}
  static int Int(object value){return value==null?0:Convert.ToInt32(value);}
  static object Stone(object actor){return Get(actor,"m_Healstone")??Get(Get(actor,"PlayerDetail"),"Healstone");}
  static void Log(object value){lock(Gate)File.AppendAllText(Path.Combine(Root,"logs","native-healing-"+System.Diagnostics.Process.GetCurrentProcess().Id+".jsonl"),new JavaScriptSerializer().Serialize(value)+Environment.NewLine);}
  static void BeforeTurn(object __instance,out Turn __state){__state=null;Current=null;if(!File.Exists(Path.Combine(Root,"config","testing.flag")))return;try{var detail=Get(__instance,"PlayerDetail");var info=Get(detail,"PlayerCharacter");var stone=Stone(__instance);if(stone==null)return;var game=Get(__instance,"Game");__state=new Turn{actor=__instance,user=Int(Get(info,"ID")),before=Int(Get(__instance,"Blood")),max=Int(Get(__instance,"MaxBlood")),stone=Int(Get(stone,"TemplateID")),nominal=Int(Get(Get(stone,"Template"),"Property2")),countBefore=Int(Get(stone,"Count")),alreadyAttacking=Convert.ToBoolean(Get(__instance,"IsAttacking")),gameType=Convert.ToString(Get(game,"GameType")),special=Convert.ToBoolean(game.GetType().GetMethod("IsSpecialPVE").Invoke(game,null))};Current=__state;}catch(Exception e){Console.WriteLine("HEAL AUDIT: "+e.GetType().Name);}}
  static void AfterTurn(object __instance,Turn __state){try{if(__state!=null)Log(new{eventName="native_turn_healing",utc=DateTime.UtcNow.ToString("o"),user=__state.user,hpBefore=__state.before,hpAfter=Int(Get(__instance,"Blood")),maxHp=__state.max,stone=__state.stone,nominal=__state.nominal,countBefore=__state.countBefore,countAfter=Int(Get(Stone(__instance),"Count")),gameType=__state.gameType,specialPve=__state.special,alreadyAttacking=__state.alreadyAttacking});}catch(Exception e){Console.WriteLine("HEAL AUDIT: "+e.GetType().Name);}finally{Current=null;}}
  static void BeforeBlood(object __instance,int __0,out int __state){__state=Current==null?0:Int(Get(__instance,"Blood"));}
  static Exception CreateFinalizer(Exception __exception){if(__exception!=null)Console.WriteLine("NATIVE GAME CREATE EXCEPTION: "+__exception);return __exception;}
  public static void WatchGames(Harmony harmony,Assembly core){
   harmony.Patch(core.GetType("Game.Logic.BaseGame").GetMethod("SendCreateGame",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance,null,new[]{core.GetType("Game.Logic.Phy.Object.Player")},null),finalizer:new HarmonyMethod(typeof(BattleAudit36).GetMethod("CreateFinalizer",BindingFlags.NonPublic|BindingFlags.Static)));
   GamesTimer=new Timer(_=>{if(!File.Exists(Path.Combine(Root,"config","testing.flag")))return;try{var raw=(IEnumerable)core.GetType("Fighting.Server.Games.GameMgr").GetMethod("GetGames",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null);var rows=raw.Cast<Game.Logic.BaseGame>().Select(g=>new{id=g.Id,state=g.GameState.ToString(),turn=g.TurnIndex,players=g.GetAllPlayers().Select(p=>new{id=p.PlayerDetail.PlayerCharacter.ID,team=p.Team,loading=p.LoadingProcess,active=p.IsActive,ready=p.Ready,hp=p.Blood}).ToArray()}).ToArray();string text=new JavaScriptSerializer().Serialize(rows);lock(Gate){if(text==LastGames)return;LastGames=text;File.AppendAllText(Path.Combine(Root,"logs","native-games-"+System.Diagnostics.Process.GetCurrentProcess().Id+".jsonl"),DateTime.UtcNow.ToString("o")+" "+text+Environment.NewLine);}}catch(Exception e){Console.WriteLine("NATIVE GAME STATE AUDIT: "+e.GetType().Name);}},null,5000,1000);
  }
  static void AfterReset(object __instance){if(!File.Exists(Path.Combine(Root,"config","testing.flag")))return;try{var detail=Get(__instance,"PlayerDetail");var info=Get(detail,"PlayerCharacter");var weapon=Get(detail,"MainWeapon");Log(new{eventName="native_combat_reset",utc=DateTime.UtcNow.ToString("o"),user=Int(Get(info,"ID")),grade=Int(Get(info,"Grade")),power=Int(Get(info,"FightPower")),attack=Get(__instance,"Attack"),defence=Get(__instance,"Defence"),agility=Get(__instance,"Agility"),luck=Get(__instance,"Lucky"),baseDamage=Get(__instance,"BaseDamage"),baseGuard=Get(__instance,"BaseGuard"),blood=Get(__instance,"MaxBlood"),energy=Get(__instance,"Energy"),weapon=Get(weapon,"TemplateID"),strengthen=Get(weapon,"StrengthenLevel"),style=Get(info,"Style"),nimbus=Get(info,"Nimbus")});}catch(Exception e){Console.WriteLine("COMBAT AUDIT: "+e.GetType().Name);}}
  static void AfterBlood(object __instance,int __0,int __state){try{var turn=Current;if(turn==null||!Object.ReferenceEquals(turn.actor,__instance))return;Log(new{eventName="native_add_blood_in_turn",utc=DateTime.UtcNow.ToString("o"),user=turn.user,stone=turn.stone,nominal=turn.nominal,requested=__0,hpBefore=__state,hpAfter=Int(Get(__instance,"Blood")),maxHp=Int(Get(__instance,"MaxBlood"))});}catch(Exception e){Console.WriteLine("HEAL AUDIT: "+e.GetType().Name);}}
  public static void Install(Harmony harmony,Type player,string root){Root=root;var flags=BindingFlags.NonPublic|BindingFlags.Static;harmony.Patch(player.GetMethod("Reset",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly),postfix:new HarmonyMethod(typeof(BattleAudit36).GetMethod("AfterReset",flags)));harmony.Patch(player.GetMethod("StartAttacking",BindingFlags.Public|BindingFlags.Instance|BindingFlags.DeclaredOnly),prefix:new HarmonyMethod(typeof(BattleAudit36).GetMethod("BeforeTurn",flags)),postfix:new HarmonyMethod(typeof(BattleAudit36).GetMethod("AfterTurn",flags)));var living=player.Assembly.GetType("Game.Logic.Phy.Object.Living",true);harmony.Patch(living.GetMethod("AddBlood",new[]{typeof(int)}),prefix:new HarmonyMethod(typeof(BattleAudit36).GetMethod("BeforeBlood",flags)),postfix:new HarmonyMethod(typeof(BattleAudit36).GetMethod("AfterBlood",flags)));}
 }
}
